from pathlib import Path
import hashlib,json,difflib
b=Path.cwd();s=b/'reference/session';step=b/'reference/step-05-execute-v2'
outputs=[s/'execution/ui-checks-v2.spec.js',s/'execution/ui-v2-observations.json',s/'evaluations/ui-v2-check.md',s/'evaluations/handoff-v2.md',s/'evaluations/plan-v2/ui-v2-review.md',step/'evaluation/evaluator.md',s/'execution/ui-v2-evaluator-runtime',s/'execution/ui-v2-evaluator-evidence.json']
