 if p.exists(): raise SystemExit('BLOCKED existing target: '+str(p))
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
assert sha(s/'ui-mockup-v2.html')==sha(step/'ui-mockup-v2.html')=='249b98c493f4c1347efe36f8be059095ede9d3b23b76ada3b022cfc416c2a1cc'
assert sha(s/'ui-contract-v2.md')==sha(step/'ui-contract-v2.md')=='40ad0ff84c423a225b1675bbc2a627390446b9ecfcbcbb4496a6f0605e675888'
r=json.loads((step/'ui-browser/script-revisions.json').read_text())
for key,hashkey in [('source','source_sha256'),('revision','revision_sha256')]: assert sha(step/'ui-browser'/r[key])==r[hashkey]
